--
-- Table structure for table `orders`
--

DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `orders` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_id` bigint unsigned DEFAULT NULL,
  `games` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `product` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `code_product` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `id_games` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `server_games` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nickname` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `whatsapp` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `code_voucher` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `promo_code_id` bigint unsigned DEFAULT NULL,
  `promo_code` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `price` bigint NOT NULL,
  `discount_price` bigint DEFAULT NULL,
  `promo_discount` bigint DEFAULT NULL,
  `profit` bigint NOT NULL,
  `fee` bigint DEFAULT NULL,
  `total_price` bigint NOT NULL,
  `payment_name` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `payment_method` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `payment_code` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `duitku_reference` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `qrispy_qris_id` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `qrispy_image_url` text COLLATE utf8mb4_unicode_ci,
  `qrispy_image_base64` longtext COLLATE utf8mb4_unicode_ci,
  `expired_time` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `qrispy_expires_at` timestamp NULL DEFAULT NULL,
  `qrispy_paid_at` timestamp NULL DEFAULT NULL,
  `qrispy_webhook_unique_id` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `payment_status` enum('UNPAID','PAID','EXPIRED','FAILED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'UNPAID',
  `payment_instructions` json DEFAULT NULL,
  `buy_status` enum('Pending','Proses','Sukses','Batal','Gagal','Unknown') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Pending',
  `serial_number` text COLLATE utf8mb4_unicode_ci,
  `df_message` text COLLATE utf8mb4_unicode_ci,
  `koalastore_message` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `orders_order_id_unique` (`order_id`),
  KEY `orders_user_id_foreign` (`user_id`),
  KEY `orders_promo_code_id_index` (`promo_code_id`),
  KEY `orders_qrispy_qris_id_index` (`qrispy_qris_id`),
  KEY `orders_qrispy_webhook_unique_id_index` (`qrispy_webhook_unique_id`)
) ENGINE=InnoDB AUTO_INCREMENT=45 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

